import{c as t,Q as o,j as a,m as d}from"./chunks/framework.DxgWTcNC.js";const m=JSON.parse('{"title":"Visual Mode, Panels, and Navigation","description":"","frontmatter":{},"headers":[],"relativePath":"part1/06-visual-mode.md","filePath":"part1/06-visual-mode.md","lastUpdated":null}'),s={name:"part1/06-visual-mode.md"};function n(r,e,c,i,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="visual-mode-panels-and-navigation" tabindex="-1">Visual Mode, Panels, and Navigation <a class="header-anchor" href="#visual-mode-panels-and-navigation" aria-label="Permalink to &quot;Visual Mode, Panels, and Navigation&quot;">​</a></h1><p>The visual mode is r2&#39;s interactive disassembly browser. It is purely keyboard-driven, fast, and surprisingly comfortable once you have the shortcuts in your fingers. This chapter covers visual mode, panels mode, and the navigation patterns that make working in r2 feel less like typing commands and more like exploring.</p><h2 id="entering-visual-mode" tabindex="-1">Entering visual mode <a class="header-anchor" href="#entering-visual-mode" aria-label="Permalink to &quot;Entering visual mode&quot;">​</a></h2><p>From the command prompt, type <code>V</code> to enter visual mode. From visual mode, <code>q</code> returns you to the prompt.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001234]&gt; V</span></span></code></pre></div><p>You are now looking at disassembly with the cursor at the current seek. The view at the top tells you what kind of view you are in:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001234 [xpdr]]&gt; sym.main:</span></span></code></pre></div><p>Press <code>p</code> to cycle through views: hex, disasm, debug, strings, decompiler, call graph. Press <code>P</code> for the reverse direction. The view name updates in the header.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>The most useful views are <strong>disasm</strong> (default), <strong>graph</strong> (<code>V</code> then <code>V</code> again — small-letter then capital), and <strong>decompiler</strong> (toggle with <code>p</code> until it says <code>pdg</code> or <code>pdd</code>).</p></div><h2 id="disassembly-view-shortcuts" tabindex="-1">Disassembly view shortcuts <a class="header-anchor" href="#disassembly-view-shortcuts" aria-label="Permalink to &quot;Disassembly view shortcuts&quot;">​</a></h2><p>Once in disasm view:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>j</code> / <code>k</code></td><td>scroll down / up by one instruction</td></tr><tr><td><code>J</code> / <code>K</code></td><td>scroll by one screen</td></tr><tr><td><code>h</code> / <code>l</code></td><td>move cursor left/right (mostly hex view)</td></tr><tr><td><code>c</code></td><td>toggle cursor mode (a small block cursor for byte-level work)</td></tr><tr><td><code>g</code></td><td>go to address (prompts)</td></tr><tr><td><code>s</code></td><td>step (in debugger mode)</td></tr><tr><td><code>S</code></td><td>step over (in debugger mode)</td></tr><tr><td><code>n</code> / <code>N</code></td><td>next / previous function</td></tr><tr><td><code>b</code></td><td>go back in the seek history</td></tr><tr><td><code>u</code> / <code>U</code></td><td>seek backward / forward in history</td></tr><tr><td><code>:</code></td><td>open a command prompt without leaving visual mode</td></tr><tr><td><code>;</code></td><td>add comment at cursor (prompts)</td></tr><tr><td><code>d</code></td><td>define cursor: function/string/data/code (prompts)</td></tr><tr><td><code>df</code></td><td>define function at cursor</td></tr><tr><td><code>dr</code></td><td>rename function at cursor</td></tr><tr><td><code>dc</code></td><td>edit calling convention</td></tr><tr><td><code>f</code></td><td>add a flag at cursor (prompts)</td></tr><tr><td><code>r</code></td><td>rename function/flag at cursor</td></tr><tr><td><code>x</code></td><td>show xrefs to current function</td></tr><tr><td><code>X</code></td><td>show xrefs from current address</td></tr><tr><td><code>/</code></td><td>search</td></tr><tr><td><code>?</code></td><td>help</td></tr></tbody></table><p>The <code>:</code> shortcut is the secret weapon. Anything you would type at the main r2 prompt — <code>pdf</code>, <code>axt</code>, <code>Ps</code>, <code>e asm.arch=...</code> — works inside visual mode by pressing <code>:</code>. So you never need to leave visual mode just to run a one-off command.</p><h2 id="graph-view" tabindex="-1">Graph view <a class="header-anchor" href="#graph-view" aria-label="Permalink to &quot;Graph view&quot;">​</a></h2><p>Press <code>V V</code> (or <code>Shift-V</code> from the disasm view) to enter graph view. This shows the current function as a control-flow graph with basic blocks as nodes and edges between them.</p><table tabindex="0"><thead><tr><th>Key</th><th>Graph view</th></tr></thead><tbody><tr><td><code>j k h l</code></td><td>move within a node</td></tr><tr><td><code>J K H L</code></td><td>move between nodes</td></tr><tr><td><code>t</code> / <code>f</code></td><td>follow true / false branch</td></tr><tr><td><code>+</code> / <code>-</code></td><td>zoom in / out</td></tr><tr><td><code>r</code></td><td>rename function</td></tr><tr><td><code>R</code></td><td>re-layout the graph</td></tr><tr><td><code>space</code></td><td>toggle between graph and linear disasm</td></tr><tr><td><code>c</code></td><td>cursor mode (write bytes, jump to specific address)</td></tr><tr><td><code>;</code></td><td>add comment</td></tr><tr><td><code>q</code></td><td>back to disasm view</td></tr></tbody></table><p>Graph view is genuinely good. For functions of more than ~30 basic blocks it is faster to navigate than linear disasm. Below that the linear view shows more context per screen.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Graph view has a per-function complexity ceiling — beyond ~500 nodes the layout pass becomes slow. For very large functions (vendor HALs that bury a 2000-block dispatcher in one routine), stay in linear disasm.</p></div><h2 id="panels-mode" tabindex="-1">Panels mode <a class="header-anchor" href="#panels-mode" aria-label="Permalink to &quot;Panels mode&quot;">​</a></h2><p><code>v</code> (lowercase) enters <strong>panels mode</strong> — a tiled multi-pane view inspired by tmux. You can have disassembly, hex, registers, stack, and the call graph all on screen simultaneously.</p><table tabindex="0"><thead><tr><th>Key</th><th>Panels mode</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>move focus between panels</td></tr><tr><td>\`</td><td>\`</td></tr><tr><td><code>-</code></td><td>split horizontally</td></tr><tr><td><code>X</code></td><td>close current panel</td></tr><tr><td><code>m</code></td><td>open menu (panels can be assigned commands)</td></tr><tr><td><code>n</code></td><td>new panel (prompts for command, e.g. <code>pxw</code>)</td></tr><tr><td><code>i</code></td><td>insert a flag</td></tr><tr><td><code>q</code></td><td>quit panels mode</td></tr></tbody></table><p>Panels are most useful when debugging — you can have disasm, registers, and stack visible at once. For static analysis a single visual disasm is often enough.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p><code>/</code> in visual mode (or <code>/?</code> at the prompt for help) opens a search.</p><table tabindex="0"><thead><tr><th>Form</th><th>What it searches</th></tr></thead><tbody><tr><td><code>/ hello</code></td><td>string literal</td></tr><tr><td><code>/x deadbeef</code></td><td>hex bytes</td></tr><tr><td><code>/v 0x12345678</code></td><td>a 4-byte little-endian value</td></tr><tr><td><code>/V 0x...</code></td><td>range search for a value</td></tr><tr><td><code>/c push ebp</code></td><td>disassembly text match</td></tr><tr><td><code>/r main</code></td><td>references to the symbol <code>main</code></td></tr><tr><td><code>/m foo</code></td><td>magic / format pattern</td></tr><tr><td><code>/a mov</code></td><td>search by mnemonic</td></tr><tr><td><code>/A mov</code></td><td>search by mnemonic family</td></tr><tr><td><code>/z 4 32</code></td><td>strings of length 4..32</td></tr></tbody></table><p>The <code>/c</code> form is the embedded reverse engineer&#39;s friend: search for a specific instruction sequence to find call gates, syscall stubs, or peripheral access patterns:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; /c ldr r0, [0x40021018]    # find every read of RCC-&gt;APB2ENR on STM32</span></span>
<span class="line"><span>[0x00]&gt; /c ldr r0, =0x40004400     # find references to USART2 base</span></span></code></pre></div><p>Results land in the flag space <code>searches</code> so you can iterate over them with <code>@@= search.*</code>.</p><h2 id="the-g-go-command" tabindex="-1">The <code>g</code> (go) command <a class="header-anchor" href="#the-g-go-command" aria-label="Permalink to &quot;The \`g\` (go) command&quot;">​</a></h2><p>Within visual mode, press <code>g</code> and r2 prompts for an address or a flag name. Flags autocomplete on <code>Tab</code>. This is faster than <code>:s addr</code> or <code>:s flag.name</code>.</p><p><code>gn</code> jumps to the next note (a comment), <code>gN</code> to the previous. Useful when you have annotated a function with reasoning.</p><h2 id="the-cursor-and-writing-bytes" tabindex="-1">The cursor and writing bytes <a class="header-anchor" href="#the-cursor-and-writing-bytes" aria-label="Permalink to &quot;The cursor and writing bytes&quot;">​</a></h2><p>In visual mode, press <code>c</code> to toggle a hex-style cursor. Now <code>h</code>/<code>l</code> move the cursor by one byte; <code>+</code> and <code>-</code> increment/decrement the byte value at the cursor. <code>i</code> inserts; <code>r</code> replaces; <code>R</code> opens a small editor.</p><p>Anything you write is queued in r2&#39;s write cache. To commit the writes to the underlying file (only if you opened it with <code>-w</code>), exit visual mode and either run <code>wb</code> (write back) or quit (r2 prompts).</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>You can write to a file you opened read-only — the writes go into the in-memory cache and affect the analysis but never touch the file. This is a feature (you can experiment with patches without risk), but it surprises people the first time. To actually patch the file, open with <code>-w</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -w firmware.bin</span></span></code></pre></div></div><h2 id="visual-configuration" tabindex="-1">Visual configuration <a class="header-anchor" href="#visual-configuration" aria-label="Permalink to &quot;Visual configuration&quot;">​</a></h2><p>A few <code>e</code>-vars improve visual mode dramatically. Add them to <code>~/.radare2rc</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>e scr.utf8 = true</span></span>
<span class="line"><span>e scr.utf8.curvy = true       # rounded box-drawing in graph view</span></span>
<span class="line"><span>e scr.html = false</span></span>
<span class="line"><span>e scr.color = 3                # 256-colour</span></span>
<span class="line"><span>e scr.theme = solarized        # try a few; consolas, behelit, gentoo, ...</span></span>
<span class="line"><span>e asm.bytes = false            # cleaner disasm</span></span>
<span class="line"><span>e asm.cmt.right = true</span></span>
<span class="line"><span>e asm.cmt.col = 60</span></span>
<span class="line"><span>e asm.lines.width = 14</span></span>
<span class="line"><span>e asm.flags.middle = 2</span></span>
<span class="line"><span>e asm.var.summary = false      # full var list</span></span>
<span class="line"><span>e asm.refptr = true            # show what a pointer points to</span></span>
<span class="line"><span>e asm.hint.pos = 0             # hint markers above / below opcodes</span></span>
<span class="line"><span>e asm.hint.cjmp = true         # show conditional jump hints</span></span>
<span class="line"><span>e asm.fcnsig = true            # show function signature line</span></span>
<span class="line"><span>e asm.calls = true             # render call comments inline</span></span></code></pre></div><p><code>scr.theme</code> is worth experimenting with. Run <code>eco</code> (no arguments) at the prompt to list all themes. <code>eco solarized</code> switches.</p><h2 id="working-productively-in-visual-mode" tabindex="-1">Working productively in visual mode <a class="header-anchor" href="#working-productively-in-visual-mode" aria-label="Permalink to &quot;Working productively in visual mode&quot;">​</a></h2><p>A daily workflow that scales:</p><ol><li>Load and analyse: <code>r2 -p projectname</code> or <code>r2 file &amp;&amp; aaa &amp;&amp; Ps name</code></li><li>Open a starting function: <code>s sym.main &amp;&amp; V</code></li><li>Read with <code>j</code>/<code>k</code>, follow calls with <code>Enter</code> on the call line, return with <code>b</code>.</li><li>Annotate as you go: <code>;</code> for comments, <code>dr</code> to rename, <code>f</code> for flags.</li><li>Switch to graph view (<code>V</code>) on complex functions; back to linear (<code>V</code> again) for simple ones.</li><li>When you find something interesting elsewhere (an xref, a string, a literal pool entry), <code>:</code> to drop into the prompt, run the lookup, <code>q</code> back to visual.</li><li>Save the project (<code>:Ps</code>) every 15 minutes or so.</li></ol><p>You will spend most of your r2 time in visual mode. Investing an hour in muscle memory here pays back the rest of your career.</p><p>That closes Part I. You should now be able to load any binary, drive analysis, and navigate the result. Part II covers the static analysis toolkit you reach for once the binary is loaded.</p>`,44)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
